() => {
  const card = document.querySelector('.card');
  const r = card.getBoundingClientRect();
  const out = {card:[r.width,r.height], overflow:[]};
  document.querySelectorAll('.inner *').forEach(el=>{
    const b = el.getBoundingClientRect();
    if (b.width===0&&b.height===0) return;
    if (b.left < r.left-0.5 || b.top < r.top-0.5 || b.right > r.right+0.5 || b.bottom > r.bottom+0.5) {
      out.overflow.push((el.className||el.tagName)+' '+JSON.stringify([b.left,b.top,b.right,b.bottom]));
    }
  });
  // check text elements not clipped
  ['.title','.name','.role','.meta','.cta','.evt'].forEach(s=>{
    const el=document.querySelector(s);
    if(!el) return;
    if (el.scrollWidth > el.clientWidth+1 || el.scrollHeight > el.clientHeight+1)
      out.overflow.push('clipped:'+s+' '+el.scrollWidth+'/'+el.clientWidth+' '+el.scrollHeight+'/'+el.clientHeight);
  });
  return out;
}

